# Public API (cmgr:*)
  @api cmgr:register(name, fn, undoDesc)  @ 125
      @contract  delegates to the global scope — root-level commands are gated-to-global, which is always reachable; the duplicated registration body now lives only in scope:register  @ 124
  @api cmgr:registerAll(tbl)  @ 126
  @api cmgr:rootKeymap()  @ 129
      @contract  returns the bottom-of-stack ('global') keymap directly — used by dispatchers that want to fire ONLY root bindings (e.g. trackerPage's swing editor wants playPause/quit live but page-scoped commands off)  @ 128
  @api cmgr:bind(name, keys)  @ 131
  @api cmgr:bindAll(tbl)  @ 132
  @api cmgr:installManifest(manifest)  @ 143-156
      @invariant  a command resolves to exactly one entry — two scopes declaring it raises  @ 140
      @contract  writes each entry's keys into its scope's keymap and hangs scope.manifest  @ 142
  @api cmgr:auditManifests()  @ 160-181
      @contract  a declared scope's entries and its registrations must correspond, both ways  @ 158
      @contract  a scope that registers a command while declaring no manifest raises  @ 159
  @api cmgr:wrap(name, wrapper)  @ 184-188
      @contract  wrap is a no-op if name has no registered command; wrappers stack (compose outward)  @ 183
  @api cmgr:doBefore(name, before)  @ 193-201
      @contract  doBefore/doAfter accept either a single name or an array of names  @ 190
      @contract  doAfter preserves the original command's return values (the dispatch signal)  @ 191
      @invariant  wraps compose inside the gate — when invoke skips a gated command, no doBefore / doAfter side-effect fires  @ 192
  @api cmgr:doAfter(name, after)  @ 203-213
  @api cmgr:beginPrefix()  @ 235
      @contract  buffer accepts only '0'..'9' and '/'; cancel/finish/invoke each leave the state inactive  @ 234
  @api cmgr:isPrefixActive()  @ 236
  @api cmgr:appendPrefix(ch)  @ 238-242
  @api cmgr:cancelPrefix()  @ 244
  @api cmgr:finishPrefix()  @ 247-265
      @contract  empty buffer or unparseable input → nil pending value; '/' with empty numerator or denominator parses as nil; integer N stored as (N/1)  @ 246
  @api cmgr:prefixRational()  @ 268-270
      @contract  non-consuming reader of the parsed rational; safe to call inside a command body. Returns (nil, nil) when no prefix is pending. State is cleared at the end of invoke, not by this call.  @ 267
  @api cmgr:scope(name)  @ 275-282
      @contract  creates the scope on first request; idempotent thereafter  @ 274
  @api cmgr:push(s)  @ 287-291
      @contract  push(name|scope); creates a named scope if absent. Top-of-stack is the most recently pushed.  @ 286
  @api cmgr:pop(s)  @ 294-298
      @contract  pop(name|scope) asserts the named scope is currently on top; pops it  @ 293
  @api cmgr:lastCommand()  @ 306
      @contract  name and serial of the last body run; unknown or gated-out changes neither  @ 305
  @api cmgr:invoke(name, ...)  @ 311-331
      @contract  returns nil when the command is unknown OR registered on a scope that is not currently reachable (off-stack or blocked by a modal above)  @ 308
      @contract  always prepends the pending prefix (defaulted to 1 when nothing is pending) as the first argument to the command body. Bodies that need to distinguish "user typed 1" from "no prefix" read prefixRational() — it returns (nil, nil) when nothing is pending. State stays live for the call so the body may read it; cleared on return ONLY if there was a pending prefix at entry, so a command body that opens prefix mode (beginPrefix) is not wiped out by its own invoke.  @ 309
      @contract  spring-loaded scope: redirect[] runs fn in-place; keepAlive[] passes; else onBail()  @ 310
  @api cmgr:keysFor(name)  @ 347
  @api cmgr:keychain()  @ 350-367
      @contract  returns one keymap per stack scope in top-down order; modal scopes filter lower keymaps to their passthrough name set, then halt the walk  @ 349
  @api cmgr:keySpec(spec, ImGui)  @ 370-375
      -- ImGui injected so cmgr stays free of REAPER-side imports at module load.
  @api cmgr:commandAtKey(spec, exceptName, ImGui)  @ 381-393
      @contract  reachable command for spec's key (keychain top-down); skips exceptName; nil if free  @ 380
  @api cmgr:bindingSite(name)  @ 396-403
      @contract  scope to edit name's binding in: scope currently binding it, else its gate scope  @ 395
  @api cmgr:noteChars(char)  @ 409-411
      -- Re-read noteLayout on each call so a config change takes effect
      -- without rebuilding vm.
  @api cmgr:keyLabel(spec, ImGui)  @ 498-510
  @api cmgr:keyLabelList(name, ImGui)  @ 513-519
      @contract  list of human labels, one per bound keyspec of the reachable command, or nil if unbound  @ 512
  @api cmgr:keyLabels(name, ImGui)  @ 522-525
      @contract  keyLabelList joined by ' / ', or nil if unbound on the current stack  @ 521
  @api cmgr:tokenForSpec(spec, ImGui)  @ 587-598
      @contract  spec -> stable ASCII token ("Ctrl+Z"); nil if the key has no token name  @ 586
  @api cmgr:specForToken(token, ImGui)  @ 601-616
      @contract  token -> keyspec (bare key | {key, mod...}); (nil, err) on an unknown key/modifier  @ 600
  -- Binding overrides (persisted, hand-editable)
  @api cmgr:loadOverrides(ImGui)  @ 622-637
      @contract  a malformed token is warned and skipped; the command keeps its other (good) bindings  @ 621
  @api cmgr:rebind(scopeName, name, specs, ImGui)  @ 640-650
      @contract  overwrites the scope's binding for name and persists it as tokens (global tier)  @ 639

